import cors from 'cors';  // npm install cors

// DANGEROUS — wildcard origin with credentials
// The browser actually blocks credentials with wildcard origin
// (Access-Control-Allow-Credentials: true + Access-Control-Allow-Origin: * is invalid)
// But this misconfiguration pattern is extremely common and confusing:
app.use(cors({ origin: '*' }));  // Fine for public APIs, bad for credentialed ones

// DANGEROUS — reflecting the Origin header (trusts ANY origin)
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', req.headers.origin);  // ← NEVER do this
  res.header('Access-Control-Allow-Credentials', 'true');
  next();
});
// This means ANY origin can read your API with user credentials
// A malicious site can read your users' private data

// SAFE — explicit allowlist of trusted origins
const ALLOWED_ORIGINS = [
  'https://myapp.com',
  'https://staging.myapp.com',
  process.env.NODE_ENV === 'development' ? 'http://localhost:5173' : '',
].filter(Boolean);

app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (mobile apps, curl, Postman)
    if (!origin || ALLOWED_ORIGINS.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS: origin ${origin} not allowed`));
    }
  },
  credentials: true,  // Allow cookies to be sent cross-origin
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400,  // Cache preflight response for 24 hours
}));
